// Generated by scripts/sync-examples.ts from scripts/example-app/src/demos/tasks/TasksDemo.tsx. Do not edit.
import { useEffect, useRef, useState } from "react";
import { now } from "../../clock";
import { Button } from "../../ui/Button";
import { ButtonRow } from "../../ui/ButtonRow";
import { Card } from "../../ui/Card";
import { InfoRow } from "../../ui/InfoRow";
import { Notice } from "../../ui/Notice";
import { ProgressBar } from "../../ui/ProgressBar";
import { SegmentedControl } from "../../ui/SegmentedControl";
import { describeError } from "../describeError";
import { countPrimesAsync } from "./primes.lucent";

type Limit = "1e8" | "1e9" | "4e9";

const LIMITS = [
  { value: "1e8", label: "100 million" },
  { value: "1e9", label: "1 billion" },
  { value: "4e9", label: "4 billion" },
] as const;

/** π(x): the published prime counts, to check the answer against. */
const KNOWN: Record<Limit, number> = { "1e8": 5761455, "1e9": 50847534, "4e9": 189961812 };

type Outcome =
  | { kind: "done"; limit: Limit; count: number; seconds: number }
  | { kind: "cancelled"; at: number }
  | { kind: "failed"; message: string };

const grouped = (n: number) => n.toLocaleString("en-US");

export function TasksDemo() {
  const [limit, setLimit] = useState<Limit>("1e9");
  const [progress, setProgress] = useState(0);
  const [running, setRunning] = useState(false);
  const [ticks, setTicks] = useState(0);
  const [outcome, setOutcome] = useState<Outcome | null>(null);
  const controller = useRef<AbortController | null>(null);

  // A JavaScript timer: it keeps ticking because the work runs on the Lucent thread.
  useEffect(() => {
    if (!running) return;

    const timer = setInterval(() => setTicks((n) => n + 1), 100);

    return () => clearInterval(timer);
  }, [running]);

  useEffect(() => () => controller.current?.abort(), []);

  async function start() {
    controller.current = new AbortController();
    setRunning(true);
    setProgress(0);
    setTicks(0);
    setOutcome(null);

    const began = now();
    let done = 0;

    try {
      const count = await countPrimesAsync(
        Number(limit),
        (share) => {
          done = share;
          setProgress(share);
        },
        controller.current.signal,
      );
      setOutcome({ kind: "done", limit, count, seconds: (now() - began) / 1000 });
    } catch (e) {
      setOutcome(
        e instanceof Error && e.name === "AbortError"
          ? { kind: "cancelled", at: done }
          : { kind: "failed", message: describeError(e) },
      );
    }

    setRunning(false);
  }

  return (
    <>
      <Card title="Count the primes below">
        <SegmentedControl testID="tasks-limit" options={LIMITS} value={limit} onChange={setLimit} />

        <ButtonRow>
          <Button testID="tasks-start" label="Start" busy={running} onPress={() => void start()} />

          {running ? (
            <Button
              testID="tasks-cancel"
              label="Cancel"
              variant="danger"
              onPress={() => controller.current?.abort()}
            />
          ) : null}
        </ButtonRow>
      </Card>

      <Card title="Progress">
        <ProgressBar value={progress} />
        <InfoRow testID="tasks-progress" label="Done" value={`${Math.floor(progress * 100)}%`} />
        <InfoRow label="JavaScript timer ticks meanwhile" value={String(ticks)} />

        {outcome?.kind === "done" ? (
          <Notice
            testID="tasks-result"
            tone={outcome.count === KNOWN[outcome.limit] ? "success" : "danger"}
            title={`${grouped(outcome.count)} primes in ${outcome.seconds.toFixed(2)} s`}
            message={
              outcome.count === KNOWN[outcome.limit]
                ? "The published count, π(x)."
                : `Expected ${grouped(KNOWN[outcome.limit])}.`
            }
          />
        ) : null}

        {outcome?.kind === "cancelled" ? (
          <Notice
            testID="tasks-result"
            tone="warning"
            title={`Cancelled at ${Math.floor(outcome.at * 100)}%`}
          />
        ) : null}

        {outcome?.kind === "failed" ? (
          <Notice tone="danger" title="Failed" message={outcome.message} />
        ) : null}
      </Card>
    </>
  );
}
